import{c as t,Q as r,j as l,m as a}from"./chunks/framework.BPmZ9ESu.js";const o="/cours/assets/09-insertion-tableau.mmsNyUZY.png",s="/cours/assets/09-options-tableau.CHtpwezU.png",i="/cours/assets/09-filtres-tableau.vSiurgdw.png",n="/cours/assets/09-tri-tableau.DvYUovp9.png",f=JSON.parse('{"title":"Tableaux, filtres et tris","description":"","frontmatter":{"title":"Tableaux, filtres et tris"},"headers":[],"relativePath":"modules/02-excel/09-tableaux-filtres-tris.md","filePath":"modules/02-excel/09-tableaux-filtres-tris.md"}'),u={name:"modules/02-excel/09-tableaux-filtres-tris.md"};function d(c,e,g,b,h,p){return r(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="tableaux-filtres-et-tris" tabindex="-1">Tableaux, filtres et tris <a class="header-anchor" href="#tableaux-filtres-et-tris" aria-label="Permalink to &quot;Tableaux, filtres et tris&quot;">​</a></h1><h2 id="exercice-associe" tabindex="-1">Exercice associé <a class="header-anchor" href="#exercice-associe" aria-label="Permalink to &quot;Exercice associé&quot;">​</a></h2><p><a href="./../../module-02/09-Tableaux%20et%20tris.xlsx" target="_blank" rel="noopener">09 – Tableaux, filtres et tris</a></p><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><ul><li>Transformer une plage en <strong>tableau Excel</strong>.</li><li>Afficher une <strong>ligne de total</strong> sans écrire de formule compliquée.</li><li>Utiliser les <strong>filtres</strong> et <strong>tris</strong> des en-têtes.</li></ul><h2 id="creation-de-tableaux" tabindex="-1">Création de tableaux <a class="header-anchor" href="#creation-de-tableaux" aria-label="Permalink to &quot;Création de tableaux&quot;">​</a></h2><p>Transformer une plage en tableau Excel.</p><h3 id="ou-est-le-bouton-«-tableau-»" tabindex="-1">Où est le bouton « Tableau » ? <a class="header-anchor" href="#ou-est-le-bouton-«-tableau-»" aria-label="Permalink to &quot;Où est le bouton « Tableau » ?&quot;">​</a></h3><ul><li>Onglet <strong>Insertion</strong> du ruban.</li><li>Groupe <strong>Tableaux</strong>.</li><li>Bouton <strong>Tableau</strong> (icône avec un petit quadrillage).</li></ul><h3 id="procedure" tabindex="-1">Procédure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procédure&quot;">​</a></h3><ol><li><strong>Sélectionner toute la plage de données (y compris la ligne d’en-tête).</strong></li><li>Aller dans <strong>Insertion &gt; Tableau</strong>.</li><li>Vérifier que la plage proposée est correcte.</li><li>Cocher <strong>Mon tableau comporte des en-têtes</strong>.</li><li>Valider avec <strong>OK</strong>.</li></ol><img src="'+o+'" alt="Insertion d&#39;un tableau" class="img-bordered"><p>Résultat :</p><ul><li>Les en-têtes ont des <strong>petites flèches</strong> de filtre.</li><li>Le tableau a un style automatique (bandes de couleur).</li></ul><h2 id="ligne-de-total" tabindex="-1">Ligne de total <a class="header-anchor" href="#ligne-de-total" aria-label="Permalink to &quot;Ligne de total&quot;">​</a></h2><p>La ligne de total permet de calculer des sommes sans écrire la fonction <strong>SOMME</strong>. On peut également étendre la formule qui est générée.</p><h3 id="ou-activer-la-ligne-de-total" tabindex="-1">Où activer la ligne de total ? <a class="header-anchor" href="#ou-activer-la-ligne-de-total" aria-label="Permalink to &quot;Où activer la ligne de total ?&quot;">​</a></h3><ul><li>Cliquer n’importe où <strong>dans le tableau</strong>.</li><li>Un nouvel onglet apparaît dans le ruban : <strong>Création de tableau</strong> ou <strong>Outils de tableau &gt; Création</strong> (selon la version).</li><li>Dans le groupe <strong>Options de style de tableau</strong> : case à cocher <strong>Ligne des totaux</strong>.</li></ul><h3 id="procedure-1" tabindex="-1">Procédure <a class="header-anchor" href="#procedure-1" aria-label="Permalink to &quot;Procédure&quot;">​</a></h3><ol><li>Cliquer dans le tableau.</li><li>Aller dans <strong>Outils de tableau &gt; Création</strong>.</li><li>Cocher <strong>Ligne des totaux</strong>.</li><li>Dans la dernière ligne qui apparaît, cliquer dans une cellule de la colonne à totaliser.</li><li>Ouvrir la petite <strong>liste déroulante</strong> qui apparaît dans la cellule (triangle) et choisir <strong>Somme</strong>.</li></ol><img src="'+s+'" alt="Options de tableau avec ligne des totaux" class="img-bordered"><h2 id="filtres" tabindex="-1">Filtres <a class="header-anchor" href="#filtres" aria-label="Permalink to &quot;Filtres&quot;">​</a></h2><p>Les filtres servent à <strong>afficher seulement certaines lignes</strong>.</p><h3 id="ou-sont-les-boutons-de-filtre" tabindex="-1">Où sont les boutons de filtre ? <a class="header-anchor" href="#ou-sont-les-boutons-de-filtre" aria-label="Permalink to &quot;Où sont les boutons de filtre ?&quot;">​</a></h3><ul><li>Dans chaque <strong>cellule d’en-tête</strong> du tableau.</li><li>Ce sont les <strong>petites flèches</strong> à droite du nom de colonne.</li></ul><h3 id="procedure-de-base" tabindex="-1">Procédure de base <a class="header-anchor" href="#procedure-de-base" aria-label="Permalink to &quot;Procédure de base&quot;">​</a></h3><ol><li>Cliquer sur la flèche dans l’en-tête de la colonne voulue.</li><li>Choisir <strong>Filtres de texte</strong> ou <strong>Filtres de nombre</strong> si nécessaire.</li><li>Cocher/décocher les valeurs à afficher.</li><li>Valider avec <strong>OK</strong>.</li></ol><img src="'+i+'" alt="Menu de filtres" class="img-bordered"><h2 id="tri" tabindex="-1">Tri <a class="header-anchor" href="#tri" aria-label="Permalink to &quot;Tri&quot;">​</a></h2><p>Le tri sert à <strong>classer les lignes</strong> (du plus petit au plus grand, ou inversement).</p><h3 id="ou-sont-les-boutons-de-tri" tabindex="-1">Où sont les boutons de tri ? <a class="header-anchor" href="#ou-sont-les-boutons-de-tri" aria-label="Permalink to &quot;Où sont les boutons de tri ?&quot;">​</a></h3><ul><li>Dans la flèche de filtre de la colonne. <ul><li>Options <strong>Trier du plus petit au plus grand</strong> / <strong>Trier du plus grand au plus petit</strong>.</li></ul></li><li>Ou dans l’onglet <strong>Données</strong> du ruban. <ul><li>Groupe <strong>Trier et filtrer</strong>.</li><li>Boutons <strong>A→Z</strong>, <strong>Z→A</strong> ou <strong>Trier…</strong>.</li></ul></li></ul><h3 id="procedure-exemple-trier-sur-une-colonne-de-mois" tabindex="-1">Procédure (exemple : trier sur une colonne de mois) <a class="header-anchor" href="#procedure-exemple-trier-sur-une-colonne-de-mois" aria-label="Permalink to &quot;Procédure (exemple : trier sur une colonne de mois)&quot;">​</a></h3><ol><li>Cliquer dans <strong>une cellule de la colonne à trier</strong> (par exemple la colonne des mois).</li><li>Ouvrir la <strong>flèche de filtre</strong> de cette colonne.</li><li>Choisir <strong>Trier du plus petit au plus grand</strong> (ou l’option demandée dans l’exercice).</li></ol><img src="'+n+'" alt="Options de tri" class="img-bordered">',35)])])}const x=t(u,[["render",d]]);export{f as __pageData,x as default};
